(() => {
'use strict';
const D=window.TAG_DEMO, $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const groups=[['primary_genres','主类型',3],['settings','故事背景',2],['story_types','故事类型',3],['tones','情绪与风格',3]], steps=['故事构想',...groups.map(g=>g[1])];
const descriptions={romance:'吸引、相处与有依据的关系回报',womens_fiction:'她的欲望、关系与自主选择',horror:'有边界的威胁与逐渐升级的恐惧',family_domestic:'日常空间、共同生活与亲密习惯',contemporary_urban:'城市资源、工作与生活半径',domestic_betrayal:'信任破裂、真相与她的回应',second_chance:'赢回信任，让原来的关系重新开始',werewolf:'身体、能力与族群规则推动故事',female_growth:'从自我理解走向有代价的自主行动',angst:'在意之后的失落、痛感与回报',sweet:'彼此看见、回应与具体的温暖'};
let S, timer, toastTimer;
function key(axis,id){return axis+'/'+id}function item(axis,id){return D.catalog.axes[axis].find(x=>x.id===id)}function label(axis,id){return item(axis,id)?.labels['zh-CN']||id}
function template(axis,id){return D.template.replace('{{axis}}',axis).replace('{{tag_id}}',id).replace('{{标签名称}}',label(axis,id))}
function reset(){clearTimeout(timer);S={page:'create',step:0,furthest:0,premise:'',title:'',selected:Object.fromEntries(groups.map(g=>[g[0],[]])),primary:null,error:'',libraryAxis:'story_types',libraryId:'domestic_betrayal',search:'',editorTab:'edit',draft:null,records:structuredClone(D.profiles),frozen:null,proposal:null,note:'',adopted:null,busy:false};openEditor('story_types','domestic_betrayal');location.hash='create';render()}
function record(axis,id){return S.records[key(axis,id)]||{markdown:template(axis,id),status:'missing',version:0,summary:''}}
function openEditor(axis,id){S.libraryAxis=axis;S.libraryId=id;S.draft=record(axis,id).markdown;S.editorTab='edit';S.error=''}
function dirty(){return S.draft!==record(S.libraryAxis,S.libraryId).markdown}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function closeDialog(){$('#dialog').close()}
function dialog(title,body,actions){$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-dialog" aria-label="关闭">×</button></div>${body}<div class="dialog-actions">${actions||'<button class="button primary" data-action="close-dialog">知道了</button>'}</div>`;if(!$('#dialog').open)$('#dialog').showModal()}
let afterDiscard=null;
function guard(next){if(S.page==='library'&&dirty()){afterDiscard=next;dialog('尚有未保存的修改','<p class="dialog-copy">离开前保留还是放弃本次编辑？</p>','<button class="button" data-action="close-dialog">继续编辑</button><button class="button danger" data-action="discard">放弃修改</button>');return}next()}
function navigate(page){guard(()=>{S.page=page;location.hash=page;S.error='';render();window.scrollTo({top:0})})}
function chips(axis,ids,primary){return ids.length?ids.map(id=>`<span class="chip ${id===primary?'primary':''}">${esc(label(axis,id))}${id===primary?' · 主':''}</span>`).join(''):'<span class="empty-value">未选择</span>'}
function selectedSummary(source=S){return groups.map(([axis,name])=>`<div class="summary-item"><div class="summary-label">${name}</div><div class="summary-chips">${chips(axis,source.selected[axis],source.primary)}</div></div>`).join('')}
function complete(step){return step===0?!!S.premise.trim():S.selected[groups[step-1][0]].length>0}
function allComplete(){return steps.every((_,i)=>complete(i))}
function validSelection(){if(!allComplete())return '请完成故事构想与四组选择。';for(const [axis,,max]of groups){const ids=S.selected[axis];if(ids.length>max)return '所选数量超出分类上限。';for(const id of ids){const r=record(axis,id);if(r.status!=='enabled')return `${label(axis,id)}尚未启用创作说明。`;if(validate(r.markdown,axis,id).length)return `${label(axis,id)}的说明需要修正。`}}if(!S.selected.primary_genres.includes(S.primary))return '请选择一个主分类。';for(const pair of D.catalog.combination_rules.mutually_exclusive_story_types){if(pair.every(id=>S.selected.story_types.includes(id)))return pair.map(id=>label('story_types',id)).join('与')+'不能同时选择。'}return ''}
function render(){document.querySelectorAll('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===(S.page==='discussion'?'create':S.page)));$('#main').innerHTML=S.page==='library'?renderLibrary():S.page==='discussion'?renderDiscussion():renderWizard();wireInputs()}
function head(eyebrow,title,subtitle,action){return `<header class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div>${action||''}</header>`}
function renderWizard(){let g=groups[S.step-1];return `<section class="shell wizard">${head('新作品 · 头脑风暴','一起把故事想完整','', '<button class="button" data-nav="library">创作元素 ↗</button>')}<nav class="steps" aria-label="创建步骤">${steps.map((name,i)=>`<button class="step ${i===S.step?'active':i<S.step?'done':''}" data-step="${i}" ${i>S.furthest?'disabled':''} ${i===S.step?'aria-current="step"':''}><span class="step-num">${i<S.step?'✓':i+1}</span><span>${name}</span></button>`).join('')}</nav><div class="wizard-grid"><div class="wizard-main">${S.step===0?premisePage():tagPage(g)}</div><aside class="side-summary"><div class="summary-title">这本故事</div><div id="selection-summary">${selectedSummary()}</div><p class="idea-excerpt">${esc(S.premise)||'从一个想法开始。'}</p></aside></div><footer class="wizard-footer"><div class="footer-left">${S.step===0?'先写下你想讲的故事':`已选 ${S.selected[g[0]].length} 项${S.step===1?' · 1 主 + 最多 2 辅':` · 最多 ${g[2]} 项`}`}</div><div class="row">${S.step>0?'<button class="button" data-action="previous">上一步</button>':''}<button id="next" class="button primary" data-action="${S.step===4?'start':'next'}" ${!complete(S.step)||S.busy?'disabled':''}>${S.busy?'整理选择…':S.step===4?'开始讨论 →':'下一步 →'}</button></div></footer></section>`}
function premisePage(){return `<div class="step-caption"><h2>你想写一个怎样的故事？</h2></div><p class="step-help">人物、处境，或者一个让你想继续写下去的瞬间。</p><label class="label" for="premise">故事构想</label><textarea id="premise" class="field premise" maxlength="30000" placeholder="例如：一段看似稳固的婚姻里，她发现了丈夫始终隐瞒的秘密……">${esc(S.premise)}</textarea><div class="field-bottom"><button class="link" data-action="sample">填入演示构想</button><span id="premise-count">${S.premise.length} 字</span></div><label class="label" for="title">暂定书名<span class="optional">选填</span></label><input id="title" class="field" maxlength="160" value="${esc(S.title)}" placeholder="可以在讨论后再决定">`}
function tagPage([axis,name,max]){const enabled=D.catalog.axes[axis].filter(x=>record(axis,x.id).status==='enabled'||S.selected[axis].includes(x.id));const missing=D.catalog.axes[axis].filter(x=>record(axis,x.id).status!=='enabled'&&!S.selected[axis].includes(x.id));const ids=S.selected[axis];return `<div class="step-caption"><h2>${name}</h2><span class="badge">至少选 1 项</span></div><p class="step-help">${axis==='primary_genres'?'首选作为主类型，其他类型也会参与故事设计。':axis==='settings'?'故事发生在怎样的生活与环境中？':axis==='story_types'?'你希望这本故事兑现哪些情节与关系？':'你希望读者在阅读时，感受到什么？'}</p><div class="tiles">${enabled.map(x=>{let chosen=ids.includes(x.id);return `<article class="tile ${chosen?'selected':''}"><button class="tile-select" aria-pressed="${chosen}" data-tag="${x.id}" data-axis="${axis}"><div class="tile-head"><span>${esc(x.labels['zh-CN'])}</span><span class="check">✓</span></div><div class="tile-desc">${record(axis,x.id).status!=='enabled'?'说明未启用 · 点击取消选择':esc(descriptions[x.id]||record(axis,x.id).summary||'使用已启用的创作说明')}</div></button>${chosen&&axis==='primary_genres'?`<button class="tile-primary" data-primary="${x.id}">${S.primary===x.id?'● 当前主类型':'设为主类型'}</button>`:''}</article>`}).join('')}</div><div class="error" role="alert">${esc(S.error)}</div>${missing.length?`<details class="more-tags"><summary>待编写说明 · ${missing.length} 项</summary><div class="more-grid">${missing.map(x=>`<button data-edit-axis="${axis}" data-edit-id="${x.id}">${esc(x.labels['zh-CN'])} ↗</button>`).join('')}</div></details>`:''}${S.step===4?`<details class="review-mini"><summary>本次选择</summary><p>${esc(S.premise)}</p>${selectedSummary()}</details>`:''}`}
function toggleTag(axis,id){const ids=S.selected[axis],i=ids.indexOf(id);if(i>=0){ids.splice(i,1);if(S.primary===id)S.primary=ids[0]||null}else{const max=groups.find(g=>g[0]===axis)[2];if(ids.length>=max){S.error=`最多选择 ${max} 项，请先取消一项。`;render();return}const exclusion=D.catalog.combination_rules.mutually_exclusive_story_types.find(p=>p.includes(id)&&p.some(x=>ids.includes(x)));if(axis==='story_types'&&exclusion){S.error='这两种故事类型在 H5 分类中互斥，请选择其中一种。';render();return}ids.push(id);if(axis==='primary_genres'&&!S.primary)S.primary=id}S.error='';render()}
function renderLibrary(){const entries=D.catalog.axes[S.libraryAxis].filter(x=>(x.labels['zh-CN']+' '+x.id+(x.id==='domestic_betrayal'?'婚姻背叛出轨':'' )).toLowerCase().includes(S.search.toLowerCase()));const r=record(S.libraryAxis,S.libraryId);const active=r.status==='enabled';return `<section class="shell library">${head('创作资料','创作元素','一个标签，一份创作说明。','<button class="button primary" data-nav="create">新建头脑风暴 →</button>')}<nav class="library-tabs" aria-label="创作元素分类">${groups.map(([axis,name])=>`<button class="tab ${axis===S.libraryAxis?'active':''}" data-library-axis="${axis}">${name}</button>`).join('')}</nav><div class="library-grid"><aside class="element-list"><input class="field search" id="search" value="${esc(S.search)}" aria-label="搜索标签" placeholder="搜索标签或别名"><div class="list-meta"><span>${entries.length} 个标签</span><span>${entries.filter(x=>record(S.libraryAxis,x.id).status==='enabled').length} 已启用</span></div><div class="list-scroll">${entries.map(x=>{const state=record(S.libraryAxis,x.id);return `<button class="element-row ${S.libraryId===x.id?'active':''}" data-element="${x.id}"><div class="name">${esc(x.labels['zh-CN'])}</div><div class="line"><span>${state.version?'v'+state.version:'待编写'}</span><span>${state.status==='enabled'?'已启用':state.status==='disabled'?'已停用':'无说明'}</span></div></button>`}).join('')||'<p class="muted tiny">没有匹配标签</p>'}</div></aside><section class="editor-area"><div class="editor-head"><div><div class="row"><h2>${esc(label(S.libraryAxis,S.libraryId))}</h2><span class="badge ${active?'':'gray'}">${active?'已启用':r.status==='disabled'?'已停用':'待编写'}</span></div><div class="editor-filename">${esc(key(S.libraryAxis,S.libraryId))}.md ${r.version?'· v'+r.version:''}</div></div><div class="row">${r.version?`<button class="small-link" data-action="toggle-enabled">${active?'停用':'启用'}</button><button class="danger-link" data-action="delete">删除说明</button>`:''}</div></div><div class="editor-tools"><div class="segmented"><button class="${S.editorTab==='edit'?'active':''}" data-editor-tab="edit">编辑</button><button class="${S.editorTab==='preview'?'active':''}" data-editor-tab="preview">预览</button></div><div class="row"><button class="small-link" data-action="download-template">下载模板</button><button class="small-link" data-action="import">导入 Markdown</button></div></div>${S.editorTab==='edit'?`<textarea id="markdown" class="editor" spellcheck="false" aria-label="创作说明 Markdown">${esc(S.draft)}</textarea>`:`<div class="md-preview">${markdown(S.draft)}</div>`}<div class="editor-status"><span id="editor-hint">${esc(S.error)||'六节正文 · 按阶段读取'}</span><span id="editor-count">${S.draft.length} 字符</span></div><footer class="editor-footer"><button class="small-link" data-action="validate">检查格式</button><div id="save-area">${saveButton()}</div></footer></section></div></section>`}
function saveButton(){return dirty()?'<div class="row"><span class="tiny muted">有未保存修改</span><button class="button primary" data-action="save">保存并启用</button></div>':'<span class="tiny muted">'+(record(S.libraryAxis,S.libraryId).version?'已保存':'从模板开始编写')+'</span>'}
const headings=['读者期待','故事作用','发散方向','组合规则','分阶段指导','避免套路'];
function validate(md,axis,id){let errors=[];const fm=md.match(/^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/);if(!fm)return ['缺少 Markdown 头部元数据。'];for(const [name,val]of Object.entries({schema:'novel-creative-element.v1',catalog_version:D.catalog.catalog_version,axis,tag_id:id})){const values=[...fm[1].matchAll(new RegExp('^'+name+':\\s*(.+)$','gm'))];if(values.length!==1||values[0][1].trim()!==val)errors.push(`${name} 必须为 ${val}。`)}if(!/^commitments:\s*\n[ \t]+[a-z][a-z0-9_]*:\s*\S/m.test(fm[1]))errors.push('至少填写一项核心承诺。');if(/\{\{[^}]+\}\}/.test(md))errors.push('请替换模板中的待填写内容。');const body=md.slice(fm[0].length);for(const h of headings){const matches=[...body.matchAll(new RegExp('^## '+h+'[ \\t]*$','gm'))];if(matches.length!==1)errors.push(`需要唯一的「${h}」章节。`);else{const content=body.slice(matches[0].index+matches[0][0].length).split(/^## /m)[0].trim();if(!content)errors.push(`「${h}」还没有内容。`)}}for(const h of ['头脑风暴','骨架','正文','评议']){const m=body.match(new RegExp('^### '+h+'[ \\t]*\\n([\\s\\S]*?)(?=^#{2,3} |$(?![\\s\\S]))','m'));if(!m||!m[1].trim())errors.push(`请填写「${h}」阶段指导。`)}return errors}
function save(){const errors=validate(S.draft,S.libraryAxis,S.libraryId);if(errors.length){S.error=errors[0];dialog('说明尚未完整',`<ul class="dialog-copy">${errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`);render();return}const r=record(S.libraryAxis,S.libraryId);S.records[key(S.libraryAxis,S.libraryId)]={markdown:S.draft,version:r.version+1,status:'enabled',summary:r.summary||'按已维护的创作说明设计故事'};S.error='';render();dialog('已保存','<div class="center"><div class="success-icon">✓</div><h2>已保存并启用</h2><p class="dialog-copy">'+esc(label(S.libraryAxis,S.libraryId))+' · v'+(r.version+1)+'<br>仅更新本页演示资料</p></div>')}
function markdown(raw){const fm=raw.match(/^---\n([\s\S]*?)\n---/);let lines=raw.slice(fm?.[0].length||0).split('\n');return (fm?`<details><summary class="muted tiny">标签身份与核心承诺</summary><pre>${esc(fm[1])}</pre></details>`:'')+lines.map(line=>{if(line.startsWith('### '))return `<h3>${esc(line.slice(4))}</h3>`;if(line.startsWith('## '))return `<h2>${esc(line.slice(3))}</h2>`;if(line.startsWith('# '))return `<h1>${esc(line.slice(2))}</h1>`;if(line.startsWith('- '))return `<p>• ${esc(line.slice(2))}</p>`;return line?`<p>${esc(line)}</p>`:''}).join('')}
function sections(md){const body=md.replace(/^---\n[\s\S]*?\n---\n/,'');const out={};const rx=/^## ([^\n]+)\n([\s\S]*?)(?=^## |$(?![\s\S]))/gm;for(const m of body.matchAll(rx))out[m[1]]=m[2].trim();return out}
function compiled(snapshot){const materials=snapshot.documents.map(d=>{const sec=sections(d.markdown);const stage=sec['分阶段指导']?.match(/### 头脑风暴\n([\s\S]*?)(?=### |$)/)?.[1]?.trim()||'';const commitments=d.markdown.match(/commitments:\n([\s\S]*?)\n---/)?.[1]||'';return {identity:key(d.axis,d.id),version:d.version,commitments:commitments.trim(),reader_promise:sec['读者期待'],story_function:sec['故事作用'],divergence:sec['发散方向'],combination:sec['组合规则'],avoid:sec['避免套路'],stage_guidance:stage}});return JSON.stringify({stage:'brainstorm',author:{premise:snapshot.premise,title:snapshot.title},selection:{catalog_version:D.catalog.catalog_version,primary_genre_id:snapshot.primary,secondary_genre_ids:snapshot.selected.primary_genres.filter(x=>x!==snapshot.primary),setting_ids:snapshot.selected.settings,story_type_ids:snapshot.selected.story_types,tone_ids:snapshot.selected.tones},task:'综合全部选择提出2–3个有因果差异的总体方案；落实每项承诺，例子只是候选。作者要求与核心承诺冲突时先列为重大决定。不得自动交付骨架。',materials},null,2)}
function previewPrompt(){if(!S.frozen)return;dialog('本次装配预览',`<p class="dialog-copy">${S.frozen.documents.length} 份已选说明 · 头脑风暴阶段 · 未发送模型</p><pre class="prompt">${esc(compiled(S.frozen))}</pre>`)}
function freeze(){return {premise:S.premise,title:S.title,selected:structuredClone(S.selected),primary:S.primary,documents:groups.flatMap(([axis])=>S.selected[axis].map(id=>({axis,id,...structuredClone(record(axis,id))})))}}
function begin(){const error=validSelection();if(error){S.error=error;render();return}if(S.frozen){dialog('重新开始讨论？','<p class="dialog-copy">本页已有一轮演示。新的设定将用于重新开始。</p>','<button class="button" data-action="close-dialog">返回修改</button><button class="button primary" data-action="confirm-start">重新开始</button>');return}start()}
function start(){closeDialog();S.frozen=freeze();S.proposal=null;S.note='';S.adopted=null;S.busy=true;render();timer=setTimeout(()=>{S.busy=false;S.page='discussion';location.hash='discussion';render();window.scrollTo(0,0)},450)}
function exampleMatch(){const f=S.frozen;return f&&f.premise===D.premise&&f.selected.primary_genres.length===1&&f.primary==='romance'&&f.selected.settings.length===1&&f.selected.settings[0]==='family_domestic'&&f.selected.story_types.length===2&&['domestic_betrayal','second_chance'].every(x=>f.selected.story_types.includes(x))&&f.selected.tones.length===2&&['angst','sweet'].every(x=>f.selected.tones.includes(x))&&f.documents.every(d=>d.markdown===D.profiles[key(d.axis,d.id)]?.markdown)}
const proposals=[{title:'先分开，再重新认识',hook:'她把共同经营的店留给丈夫，带走自己一直未被认真对待的创意。分开之后，他们第一次需要在没有旧分工的情况下面对彼此。',opening:'纪念日晚餐前，她在他为别人挑选的礼物中，认出了自己当年提过却被忘记的愿望。',middle:'她的新事业遭遇困难，他能提供帮助，却必须先学会不把帮助变成重新掌控。她也发现自己过去用退让交换了安稳。',ending:'他在看不到复合希望时仍承担自己的责任。她在能够独立生活之后，主动给这段改变了的关系一次新的开始。',trade:'离别带来的痛感更强，重建需要留足相处和观察的篇幅。'},
{title:'住在一起，不再照旧',hook:'他们因尚未完成的共同事业暂时同住。她停止替他维护一切，看似熟悉的家，让彼此第一次无法躲进旧习惯。',opening:'她照常做了晚饭，却只摆下自己的餐具。丈夫下意识等她处理第二天的麻烦，才发现她这次真的没有接手。',middle:'她有了新的计划，他的补偿总落不到她真正需要的地方。一次他原本可以推给她的困难，迫使他作出没有回报保证的选择。',ending:'共同生活的细节发生真正变化。她选择留下，是因为彼此能够重新靠近，而不是因为她没有别的生活。',trade:'日常场景更亲密，必须让每次相处改变关系，避免重复拉扯。'},
{title:'失去事业之后的坦白',hook:'她准备离开时，两人共同创办的店遭遇危机。他有机会继续用谎言保住体面，却选择让她知道全部真相，连同自己的失败。',opening:'她在店庆的掌声里收到一条私人消息；眼前仍是两人十年的合影，她却第一次不知道他在看谁。',middle:'她先保住自己的创作和合作伙伴，再决定是否参与挽救共同事业。合作让他们重新看见彼此，也暴露更难面对的旧伤。',ending:'事业的恢复不自动换来原谅。经过共同工作之外的持续改变，她才愿意与他重新建立关系。',trade:'外部事件推进更快，需要让事业始终服务关系变化。'}];
function renderDiscussion(){if(!S.frozen){S.page='create';return renderWizard()}const f=S.frozen;return `<section class="shell discussion">${head('头脑风暴','先决定这本故事的走向','', '<button class="button" data-action="edit-basics">修改设定</button>')}<div class="discussion-top"><h2>总体方案 <span class="badge gray">预设演示</span></h2><button class="link" data-action="prompt">查看装配预览 ↗</button></div><div class="brief-bar"><p>${esc(f.premise)}</p><div class="source-tags">${groups.map(([axis])=>chips(axis,f.selected[axis],f.primary)).join('')}</div></div>${S.adopted?`<div class="adopted"><h3>已采用：${esc(proposals[S.adopted.index].title)}</h3><p>${esc(S.adopted.note||'没有额外补充')}</p><p class="muted tiny">演示已记录决定，未发起下一轮模型调用。</p></div>`:''}${exampleMatch()?`<div class="proposal-grid">${proposals.map((p,i)=>`<article class="proposal ${S.proposal===i?'selected':''}"><div class="proposal-no">方案 0${i+1}</div><h3>${p.title}</h3><p>${p.hook}</p><details><summary>展开故事走向</summary><p><b>开篇</b> · ${p.opening}</p><p><b>中段</b> · ${p.middle}</p><p><b>结局</b> · ${p.ending}</p><p class="muted"><b>取舍</b> · ${p.trade}</p></details><button class="button ${S.proposal===i?'selected':''}" aria-pressed="${S.proposal===i}" data-proposal="${i}">${S.proposal===i?'✓ 已选择':'采用这个方向'}</button></article>`).join('')}</div><div class="composer"><label class="label" for="note">你的补充<span class="optional">选填</span></label><textarea class="field" id="note" placeholder="可以补充你想保留的人物、情节或不同想法">${esc(S.note)}</textarea><div class="row spread"><span class="tiny muted">${S.proposal===null?'请先选一个总体方向':'已选择方案 0'+(S.proposal+1)}</span><button class="button primary" data-action="adopt" ${S.proposal===null?'disabled':''}>采用并继续 →</button></div></div>`:`<div class="notice"><h3>你的设定已整理</h3><p class="dialog-copy">本稿未接入模型，可查看所选 Markdown 的装配结果。</p><button class="link" data-action="demo-discussion">查看一轮预设讨论示例 →</button></div>`}</section>`}
function wireInputs(){const premise=$('#premise');if(premise)premise.addEventListener('input',e=>{S.premise=e.target.value;$('#premise-count').textContent=S.premise.length+' 字';$('#next').disabled=!S.premise.trim();$('.idea-excerpt').textContent=S.premise||'从一个想法开始。'});$('#title')?.addEventListener('input',e=>S.title=e.target.value);$('#markdown')?.addEventListener('input',e=>{S.draft=e.target.value;$('#save-area').innerHTML=saveButton();$('#editor-count').textContent=S.draft.length+' 字符';$('#editor-hint').textContent='尚未保存';S.error=''});$('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;S.search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)});$('#note')?.addEventListener('input',e=>S.note=e.target.value)}
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const t=e.target.closest('button,a[data-nav]');if(!t||t.disabled)return;if(t.dataset.nav){e.preventDefault();navigate(t.dataset.nav);return}if(t.dataset.step!==undefined){const to=Number(t.dataset.step);if(to<=S.furthest){if(to>S.step&&!Array.from({length:to},(_,i)=>complete(i)).every(Boolean)){toast('请先完成前面的步骤。');return}S.step=to;S.error='';render()}return}if(t.dataset.tag){toggleTag(t.dataset.axis,t.dataset.tag);return}if(t.dataset.primary){S.primary=t.dataset.primary;render();return}if(t.dataset.libraryAxis){guard(()=>{openEditor(t.dataset.libraryAxis,D.catalog.axes[t.dataset.libraryAxis][0].id);S.search='';render()});return}if(t.dataset.element){guard(()=>{openEditor(S.libraryAxis,t.dataset.element);render()});return}if(t.dataset.editAxis){navigate('library');openEditor(t.dataset.editAxis,t.dataset.editId);render();return}if(t.dataset.editorTab){S.editorTab=t.dataset.editorTab;render();return}if(t.dataset.proposal!==undefined){S.proposal=Number(t.dataset.proposal);render();return}
const a=t.dataset.action;
if(t.id==='reset'){dialog('重置演示？','<p class="dialog-copy">清除本页编辑与选择，恢复默认示例。</p>','<button class="button" data-action="close-dialog">取消</button><button class="button primary" data-action="reset-all">重置</button>');return}
if(a==='close-dialog'){closeDialog();return}if(a==='reset-all'){closeDialog();reset();return}if(a==='discard'){closeDialog();S.draft=record(S.libraryAxis,S.libraryId).markdown;const cb=afterDiscard;afterDiscard=null;cb?.();return}if(a==='sample'){S.premise=D.premise;render();return}if(a==='next'){if(complete(S.step)){S.step++;S.furthest=Math.max(S.furthest,S.step);S.error='';render();$('.wizard-main').scrollTop=0}return}if(a==='previous'){S.step=Math.max(0,S.step-1);S.error='';render();return}if(a==='start'){begin();return}if(a==='confirm-start'){start();return}if(a==='save'){save();return}if(a==='validate'){const errors=validate(S.draft,S.libraryAxis,S.libraryId);dialog(errors.length?'请完善说明':'格式检查通过',errors.length?`<ul class="dialog-copy">${errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p class="dialog-copy">标签身份、核心承诺和阶段章节齐全。内容效果仍需实际创作验证。</p>');return}
if(a==='download-template'){download(template(S.libraryAxis,S.libraryId),S.libraryId+'.template.md');return}if(a==='import'){const input=document.createElement('input');input.type='file';input.accept='.md,text/markdown,text/plain';input.addEventListener('change',async()=>{const file=input.files[0];if(!file)return;if(file.size>100000){toast('演示导入上限为 100 KB。');return}S.draft=await file.text();S.editorTab='edit';render();toast('已载入编辑区，尚未保存。')});input.click();return}
if(a==='toggle-enabled'){guard(()=>{const r=record(S.libraryAxis,S.libraryId);if(r.status!=='enabled'&&validate(r.markdown,S.libraryAxis,S.libraryId).length){toast('请先完善创作说明。');return}r.status=r.status==='enabled'?'disabled':'enabled';render();toast(r.status==='enabled'?'已启用演示说明':'已停用演示说明')});return}if(a==='delete'){dialog('删除这份说明？','<p class="dialog-copy">标签保留在分类字典中。本页已开始的讨论继续使用原快照。</p>','<button class="button" data-action="close-dialog">取消</button><button class="button danger" data-action="confirm-delete">删除说明</button>');return}if(a==='confirm-delete'){delete S.records[key(S.libraryAxis,S.libraryId)];openEditor(S.libraryAxis,S.libraryId);closeDialog();render();toast('已删除演示说明');return}if(a==='prompt'){previewPrompt();return}if(a==='edit-basics'){S.page='create';S.step=0;location.hash='create';render();return}if(a==='adopt'){if(S.proposal===null)return;S.adopted={index:S.proposal,note:S.note};render();toast('已记录演示决定');return}
if(a==='demo-discussion'){dialog('打开预设示例？','<p class="dialog-copy">将切换为“家庭背叛＋第二次机会”的固定示例；自填内容不会被模型处理。</p>','<button class="button" data-action="close-dialog">取消</button><button class="button primary" data-action="load-demo">查看示例</button>');return}if(a==='load-demo'){closeDialog();S.premise=D.premise;S.title='';S.selected={primary_genres:['romance'],settings:['family_domestic'],story_types:['domestic_betrayal','second_chance'],tones:['angst','sweet']};S.primary='romance';S.furthest=4;S.proposal=null;S.note='';S.adopted=null;S.frozen={...freeze(),documents:groups.flatMap(([axis])=>S.selected[axis].map(id=>({axis,id,...structuredClone(D.profiles[key(axis,id)])})))};S.page='discussion';render();return}
});
window.addEventListener('hashchange',()=>{const route=location.hash.slice(1);if(['create','library','discussion'].includes(route)&&route!==S.page){history.replaceState(null,'','#'+S.page);navigate(route)}});
window.addEventListener('beforeunload',e=>{if(S&&dirty()){e.preventDefault();e.returnValue=''}});
const initialHash=location.hash;reset();if(initialHash==='#library'){S.page='library';location.hash='library';render()}
})();
